export type ProfilePlatformDefinition = (typeof profilePlatformCatalog)[number];
export type ProfilePlatformId = ProfilePlatformDefinition['id'];
export type ProfilePlatformMatch = { readonly host: string; readonly pathPrefix: string; readonly subdomains: boolean };
export type ProfilePlatformMetric = { sourceWidth: number; sourceHeight: number; left: number; top: number; width: number; height: number };

const mapProfilePlatforms = <T>(select: (platform: ProfilePlatformDefinition) => T): Record<ProfilePlatformId, T> => {
  const values = {} as Record<ProfilePlatformId, T>;
  for (const platform of profilePlatformCatalog) values[platform.id] = select(platform);
  return values;
};

export const profilePlatformIds = profilePlatformCatalog.map((platform) => platform.id);
export const profilePlatformNames = mapProfilePlatforms<string>((platform) => platform.name);
export const profilePlatformFiles = mapProfilePlatforms<string>((platform) => platform.asset.file);
export const profilePlatformMetrics = mapProfilePlatforms<ProfilePlatformMetric>((platform) => {
  const { file: _file, ...metric } = platform.asset;
  return metric;
});
export const profilePlatformDomains = mapProfilePlatforms<readonly string[]>((platform) => platform.domains);
export const profilePlatformMatches = mapProfilePlatforms<readonly ProfilePlatformMatch[]>((platform) => platform.matches);
